; F1 (PSW at reset, POP PSW / SAHF masks, LAHF, FLAG, RETI into bank 6 and back). Generated by validation/v35s/onchip.py emit: the
; image also preloads the vector stubs and the data in onchip.py.
    BR main
handler:                ; 0103h: AL = the vector (from the stub)
    MOV BL, AL
    XOR AW, AW
    MOV DS0, AW
    MOV [7E00h], BL
    MOV BP, SP
    MOV AW, [BP]
    MOV [7E02h], AW
    MOV AW, [BP+2]
    MOV [7E04h], AW
    MOV AW, [BP+4]
    MOV [7E06h], AW
    MOV [7E08h], SP
    MOV AH, 02h         ; BRKI = 1: the OUT below does not trap
    MOV PSW, AH
    MOV DW, 0FF02h
    OUT DW, AL
    HALT
hspin:
    BR hspin
main:
    XOR AW, AW
    MOV SS, AW
    MOV SP, 7FFEh
    PUSH PSW
    POP CW
    DI
    MOV BW, 0B0B1h
    MOV DW, 0D0D1h
    MOV BP, 0B2B3h
