pre6:
    DB 26h
    MOV [BW], AW
    ADD AW, 0202h
    INC BW
    INC BW
    DBNZ pre6
    DB 26h
    MOV word [0FEE0h], 0E1E0h
    DB 26h
    MOV word [0FEE2h], 0E3E2h
