    MOV word [0FECEh], 0F000h
    DB 26h
    MOV word [0FECCh], 0100h
    MOV AW, 7A7Ah
    MOV CW, 7C7Ch
    ; the frame: PSW E002 (RB 6), PS 0000, PC 3000h
    MOV BW, 0E002h
    PUSH BW
    XOR BW, BW
    PUSH BW
    MOV BW, 3000h
    PUSH BW
    RETI
back7:
    MOV [00F0h], SP
    MOV [00F2h], AW
    MOV [00F4h], CW
    PUSH PSW
    POP CW
    MOV [00F6h], CW
    MOV BW, 0FEC0h
    MOV IY, 0100h
    MOV CW, 0040h
dump:
    DB 26h
    MOV AL, [BW]
    MOV [IY], AL
    INC BW
    INC IY
    DBNZ dump
    MOV DW, 0FF00h
    OUT DW, AL
    HALT
done:
    BR done

